#include <iostream>
#include <sstream>
#include <string>
#include <iomanip>
#include <vector>

struct AccountRecord {
    unsigned int id;
    std::string name;
    double balance;
};

int main() {
    // Simulating standard input with three client records
    std::string mockInput = "100 Jones 24.98\n200 Doe 345.67\n300 White 0.00\n";
    std::istringstream inputStream(mockInput);
    std::ostringstream fileBuffer; // Simulates sequential file write stream

    std::cout << "Enter the account, name, and balance.\n";
    std::cout << "Enter EOF to end input.\n";

    unsigned int account;
    std::string name;
    double balance;

    // Emulate sequential write loop
    while (inputStream >> account >> name >> balance) {
        // Formatted write equivalent to fprintf(cfPtr, "%d %s %.2f\n", ...)
        fileBuffer << account << " " << name << " " 
                   << std::fixed << std::setprecision(2) << balance << "\n";
        std::cout << "? Record written for account " << account << "\n";
    }

    std::cout << "\n[File contents of clients.txt successfully saved]:\n";
    std::cout << fileBuffer.str();
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <optional>

struct FileControlBlock {
    std::string filename;
    std::string mode;
    size_t sizeBytes;
};

// Conceptual simulation of the OS Open File Table
class KernelOpenFileTable {
private:
    std::vector<std::optional<FileControlBlock>> entries;
public:
    KernelOpenFileTable() : entries(10, std::nullopt) {}

    int registerOpen(const std::string& name, const std::string& mode) {
        for (int i = 3; i < static_cast<int>(entries.size()); ++i) {
            if (!entries[i].has_value()) {
                entries[i] = FileControlBlock{name, mode, 0};
                return i; // returns file descriptor index (e.g. 7)
            }
        }
        return -1; // table full
    }

    void displayDescriptorInfo(int fd) const {
        if (fd >= 0 && fd < static_cast<int>(entries.size()) && entries[fd].has_value()) {
            std::cout << "Descriptor [" << fd << "] maps to FCB for: " 
                      << entries[fd]->filename << " (mode: " << entries[fd]->mode << ")\n";
        }
    }
};

int main() {
    KernelOpenFileTable osTable;

    // Simulating user call: cfPtr = fopen("clients.dat", "w");
    int descriptor = osTable.registerOpen("clients.dat", "w");

    std::cout << "User space: cfPtr holds FILE struct with internal descriptor: " 
              << descriptor << "\n";

    std::cout << "Kernel space verification:\n";
    osTable.displayDescriptorInfo(descriptor);

    // Mode comparison demonstration
    std::cout << "\nMode characteristics:\n";
    std::cout << "- 'w'  : Creates/Truncates file.\n";
    std::cout << "- 'r+' : Updates existing file without truncation.\n";
    std::cout << "- 'wx' : (C11) Exclusive mode; fails if file already exists.\n";
    return 0;
}
